 string snapshotKey="",snapshotUrl="";DateTime snapshotAt;Microsoft.Web.WebView2.WinForms.WebView2? snapshotView;BrowserSnapshot? lastSnapshot;
 public async Task<BrowserSnapshot> Snapshot(CancellationToken ct){await Init();ct.ThrowIfCancellationRequested();if(CurrentUrl!="about:blank")await Validate(CurrentUrl);snapshotKey=Guid.NewGuid().ToString("N");snapshotUrl=CurrentUrl;snapshotAt=DateTime.UtcNow;snapshotView=active;using var stream=typeof(BrowserWindow).Assembly.GetManifestResourceStream("LocalChat.browser-dom.js")??throw new Exception("DOM-модуль не найден");using var reader=new StreamReader(stream);string script=(await reader.ReadToEndAsync(ct)).Replace("__NORA_NONCE__",JsonSerializer.Serialize(snapshotKey));string json=await active!.CoreWebView2.ExecuteScriptAsync(script);ct.ThrowIfCancellationRequested();lastSnapshot=JsonSerializer.Deserialize<BrowserSnapshot>(json,Disk.Json)??throw new Exception("Нет данных страницы");return lastSnapshot;}
 public async Task ActOnElement(int index,string? text,CancellationToken ct){ct.ThrowIfCancellationRequested();if(lastSnapshot==null||snapshotView!=active||snapshotUrl!=CurrentUrl||DateTime.UtcNow-snapshotAt>TimeSpan.FromSeconds(60))throw new Exception("Сначала обнови browser_snapshot: страница изменилась.");var e=lastSnapshot.Elements.SingleOrDefault(e=>e.Index==index)??throw new Exception("Нет элемента с таким index");BrowserAutomation.Validate(e,text);if(CurrentUrl!="about:blank")await Validate(CurrentUrl);string json=await active!.CoreWebView2.ExecuteScriptAsync(BrowserAutomation.Script(snapshotKey+"-"+index,text));using var d=JsonDocument.Parse(json);if(d.RootElement.ValueKind!=JsonValueKind.Object||!d.RootElement.TryGetProperty("ok",out var ok)||!ok.GetBoolean())throw new Exception("Действие не подтверждено страницей: обнови snapshot. Возможно, элемент изменился или защищён.");snapshotAt=DateTime.MinValue;}
 public async Task ScrollPage(int direction,CancellationToken ct){ct.ThrowIfCancellationRequested();if(direction is < -3 or >3||direction==0)throw new Exception("browser_scroll index: от -3 до -1 или от 1 до 3");await Init();if(CurrentUrl!="about:blank")await Validate(CurrentUrl);await active!.CoreWebView2.ExecuteScriptAsync("scrollBy(0,innerHeight*"+direction+"*0.7)");await Task.Delay(150,ct);}
